import re, pathlib

p=pathlib.Path('app.js')
s=p.read_text(encoding='utf-8')

shell = r'''function shell(content){const activeQuiz=!!(quiz&&!quiz.saved);return `<div class="shell ${activeQuiz?'quiz-shell':''}">${topbar()}<main>${content}</main>${activeQuiz?'':nav()}${activeQuiz?'':`<button class="prof-fab" data-action="open-prof" aria-label="Abrir Prof. Caramelo"><img src="${mascotUrl}" alt="Prof. Caramelo"><span>Prof. Caramelo</span></button>`}<div id="profPanel"></div></div>`}'''
s,n=re.subn(r'function shell\(content\)\{.*?\}\nfunction splash',shell+'\nfunction splash',s,count=1,flags=re.S)
if n!=1: raise SystemExit('shell patch failed')

dash = r'''function desempenho(){const agg={};AREAS.forEach(a=>agg[a]={correct:0,total:0});state.history.forEach(h=>{if(h.breakdown)Object.entries(h.breakdown).forEach(([a,v])=>{if(agg[a]){agg[a].correct+=v.correct;agg[a].total+=v.total}});else if(agg[h.area]){agg[h.area].correct+=h.correct;agg[h.area].total+=h.total}});const total=state.history.reduce((s,h)=>s+h.total,0),correct=state.history.reduce((s,h)=>s+h.correct,0),accuracy=pct(correct,total);const chosen=state.selfReportedWeak||'Não informado';const detected=AREAS.slice().sort((a,b)=>{const pa=agg[a].total?pct(agg[a].correct,agg[a].total):state.difficultyScores[a],pb=agg[b].total?pct(agg[b].correct,agg[b].total):state.difficultyScores[b];return pa-pb})[0];const recent=state.history.slice(-6);return `<section class="metrics-hero"><span class="eyebrow">📊 PAINEL DE MÉTRICAS</span><h1>Sua evolução</h1><div class="focus-summary"><div><small>🎯 FOCO ESCOLHIDO</small><b>${chosen}</b></div><div><small>🔎 PONTO FRACO DETECTADO</small><b>${detected}</b></div></div><div class="streak-banner"><img src="${mascotUrl}"><div><small>SEQUÊNCIA DE ESTUDO</small><b>${state.streak} ${state.streak===1?'dia seguido':'dias seguidos'}</b></div></div></section><div class="dashboard-grid"><article class="dash-card blue-card"><span>📝</span><small>QUESTÕES RESPONDIDAS</small><strong>${total}</strong></article><article class="dash-card yellow-card"><span>🎯</span><small>TAXA DE ACERTO GERAL</small><strong>${accuracy}%</strong></article><article class="dash-card green-card"><span>📋</span><small>SIMULADOS REALIZADOS</small><strong>${state.history.length}</strong></article><article class="dash-card aqua-card"><span>🔥</span><small>SEQUÊNCIA DE ESTUDO</small><strong>${state.streak}d</strong></article><article class="dash-card blue-card"><span>⭐</span><small>XP TOTAL</small><strong>${state.xp}</strong></article></div><section class="metric-section"><h2>📈 Evolução do desempenho</h2><div class="evolution-chart">${recent.length?recent.map(h=>{const pp=pct(h.correct,h.total);return `<div class="evo-col"><b>${pp}%</b><i style="height:${Math.max(12,pp)}%"></i><small>${h.date.slice(0,5)}</small></div>`}).join(''):'<p class="muted">Conclua simulados para acompanhar sua evolução.</p>'}</div></section><section class="metric-section"><h2>📚 Desempenho por área</h2>${AREAS.map(a=>{const pp=agg[a].total?pct(agg[a].correct,agg[a].total):state.difficultyScores[a];return `<div class="area-metric"><div><b>${a}</b><span>${pp}%</span></div><div class="progress"><i style="width:${pp}%"></i></div><small>${agg[a].total?`${agg[a].correct}/${agg[a].total} acertos`:'estimativa do diagnóstico'}</small></div>`}).join('')}</section><section class="priority-card"><h2>🐶 Prof. Caramelo recomenda</h2><p><b>Prioridade principal:</b> ${chosen}. ${detected!==chosen?`Seu desempenho recente também indica reforço em <b>${detected}</b>.`:'Seu desempenho confirma que esta área merece atenção extra.'} Vou equilibrar as demais matérias sem substituir sua escolha. ✨</p><button class="primary" data-action="personal-study">Treinar meu foco principal</button></section>`}'''
s,n=re.subn(r'function desempenho\(\)\{.*?\}\n\nfunction simulados',dash+'\n\nfunction simulados',s,count=1,flags=re.S)
if n!=1: raise SystemExit('desempenho patch failed')

helpers = r'''
function inferTopic(q){const t=((q.q||'')+' '+(q.context||'')+' '+(q.a||[]).join(' ')).toLowerCase();const maps=[
['Matemática',[['geometria',['pirâmide','polígono','área','volume','ângulo','triângulo','circunferência']],['porcentagem',['porcent','percent','taxa']],['funções',['função','gráfico','equação']],['probabilidade e estatística',['probabilidade','média','mediana','desvio','frequência']],['razão e proporção',['razão','proporção','escala']]]],
['Linguagens',[['interpretação de texto',['trecho','texto','autor','sentido','efeito','linguagem']],['coesão e semântica',['conectivo','referência','pronome','coesão']],['gêneros textuais',['gênero','charge','anúncio','poema','crônica']]]],
['Humanas',[['história do Brasil',['república','império','ditadura','brasil colônia']],['geopolítica',['território','globalização','fronteira','migração']],['cidadania e sociedade',['cidadania','direitos','sociedade','trabalho']]]],
['Natureza',[['ecologia',['ecossistema','poluição','rio','ambiente','energia']],['física',['potência','velocidade','força','energia','onda','bluetooth']],['química',['reação','mol','ácido','base','substância']],['biologia',['célula','genética','organismo','vírus','bactéria']]]]
];for(const [area,topics] of maps){if(q.area===area)for(const [topic,keys] of topics)if(keys.some(k=>t.includes(k)))return topic}return q.area==='Matemática'?'resolução de problemas':q.area==='Linguagens'?'interpretação de texto':q.area==='Humanas'?'análise histórico-social':'fenômenos naturais'}
function questionSkill(q){const topic=inferTopic(q);return q.area==='Linguagens'?`Localizar evidências e interpretar ${topic}`:q.area==='Matemática'?`Modelar e resolver problemas de ${topic}`:q.area==='Humanas'?`Relacionar contexto, causa e consequência em ${topic}`:`Aplicar conceitos de ${topic} a situações-problema`}
function reviewExplanation(q,answer){const topic=inferTopic(q),letter=String.fromCharCode(65+q.c),correct=questionText(q.a[q.c]);if(answer===q.c)return `Você identificou corretamente a alternativa ${letter}. O ponto central desta questão é ${topic}.`;return `A alternativa ${letter} é a correta. Para chegar nela, identifique primeiro o conceito de ${topic}, confronte cada alternativa com o comando e elimine as opções que não respondem exatamente ao que foi pedido. Resposta esperada: ${correct}`}
'''
s=s.replace('function quizView(){',helpers+'\nfunction quizView(){',1)

finish = r'''function finishQuiz(){const correct=quiz.items.reduce((sum,q,i)=>sum+(quiz.answers[i]===q.c),0),total=quiz.items.length,p=pct(correct,total),elapsed=Math.max(1,Math.round((Date.now()-quiz.started)/1000));if(!quiz.saved){quiz.saved=true;studyActivity(correct*10+10);quiz.items.forEach(q=>{if(!state.seenQuestionIds.includes(q.id))state.seenQuestionIds.push(q.id)});const breakdown={};AREAS.forEach(a=>breakdown[a]={correct:0,total:0});quiz.items.forEach((q,i)=>{breakdown[q.area].total++;if(quiz.answers[i]===q.c)breakdown[q.area].correct++});AREAS.forEach(a=>{if(breakdown[a].total){const score=pct(breakdown[a].correct,breakdown[a].total);state.difficultyScores[a]=Math.round(state.difficultyScores[a]*.65+score*.35)}});state.history.push({area:quiz.area,total,correct,date:new Date().toLocaleDateString('pt-BR'),elapsed,items:quiz.items,answers:quiz.answers,breakdown});save()}const errors=quiz.items.map((q,i)=>({q,i})).filter(x=>quiz.answers[x.i]!==x.q.c);const counts={};errors.forEach(({q})=>{const t=inferTopic(q);counts[t]=(counts[t]||0)+1});const priorities=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);const mins=Math.floor(elapsed/60),secs=elapsed%60;return `<div class="result"><span class="eyebrow">SIMULADO CONCLUÍDO</span><h1>${correct} / ${total}</h1><div class="score-circle">${p}%</div><h2>${p>=70?'Muito bem! 🎉':'Vamos transformar seus erros em revisão 📚'}</h2><div class="result-recommendation"><b>🐶 Prof. Caramelo recomenda</b><p>${priorities.length?`Revise primeiro: <strong>${priorities.join(', ')}</strong>.`:'Você acertou tudo. Continue revisando para consolidar o conteúdo.'}</p></div><div class="result-metrics"><div><small>Tempo total</small><b>${mins}:${String(secs).padStart(2,'0')}</b></div><div><small>Média/questão</small><b>${Math.round(elapsed/total)}s</b></div><div><small>Acertos</small><b>${correct}</b></div><div><small>Erros</small><b>${total-correct}</b></div></div><div class="result-actions"><button data-action="review-current">🔎 Analisar questões</button><button data-tab="desempenho">📊 Métricas</button><button data-action="restart-current">↻ Refazer</button></div><button class="primary full" data-action="new-quiz">Criar novo simulado</button></div>`}
function reviewHtml(items,answers){return `<div class="page-head"><div><span class="eyebrow">ANÁLISE</span><h1>Revisão do simulado</h1></div><button class="ghost" data-action="new-quiz">Voltar</button></div>${items.map((q,i)=>{const ok=answers[i]===q.c,topic=inferTopic(q);return `<article class="review-card ${ok?'ok':'no'}"><span>${ok?'✅':'❌'} Questão ${i+1} • ${q.area}${q.year?' • '+q.year:''}</span><h3>${questionText(q.q)}</h3><div class="review-tags"><span>📚 ${topic}</span><span>🎯 ${questionSkill(q)}</span></div><p><b>Sua resposta:</b> ${answers[i]==null?'Não respondida':`${String.fromCharCode(65+answers[i])} — ${questionText(q.a[answers[i]])}`}</p><p><b>Correta:</b> ${String.fromCharCode(65+q.c)} — ${questionText(q.a[q.c])}</p><div class="review-explain"><b>${ok?'Por que você acertou':'Como melhorar'}</b><p>${reviewExplanation(q,answers[i])}</p></div></article>`}).join('')}`}'''
s,n=re.subn(r'function finishQuiz\(\)\{.*?\}\nfunction reviewHtml\(items,answers\)\{.*?\}\n\nfunction redacao',finish+'\n\nfunction redacao',s,count=1,flags=re.S)
if n!=1: raise SystemExit('finish/review patch failed')

wizard = r'''let onboardingStep=0,onboardingAnswers=[null,null,null,null];
function diagnosticOverlay(){const qs=[['Qual área você sente mais dificuldade?',['Linguagens','Humanas','Natureza','Matemática']],['Como você avalia sua interpretação de textos?',['Preciso melhorar muito','Razoável','Boa','Muito boa']],['Como você se sente em Matemática?',['Tenho muita dificuldade','Oscilo bastante','Consigo resolver boa parte','É meu ponto forte']],['Quantos dias por semana pretende estudar?',['2–3 dias','4 dias','5 dias','Todos os dias']]],q=qs[onboardingStep];return `<div class="onboarding"><div class="onboard-card compact"><img src="${mascotUrl}"><span class="eyebrow">BEM-VINDO AO ESTUDAI</span><div class="wizard-progress"><i style="width:${(onboardingStep+1)/4*100}%"></i></div><small>Etapa ${onboardingStep+1} de 4</small><h1>${onboardingStep===0?'Vamos montar seu plano?':'Só mais um pouco 🐶'}</h1><div class="survey-q single"><b>${q[0]}</b>${q[1].map((a,j)=>`<button class="survey-choice ${onboardingAnswers[onboardingStep]===j?'selected':''}" data-survey-answer="${j}">${a}</button>`).join('')}</div><button class="primary full" data-action="${onboardingStep===3?'start-diagnostic':'next-survey'}" ${onboardingAnswers[onboardingStep]==null?'disabled':''}>${onboardingStep===3?'Fazer diagnóstico rápido →':'Continuar →'}</button></div></div>`}
function startDiagnostic(){if(onboardingAnswers[0]!=null){state.selfReportedWeak=AREAS[onboardingAnswers[0]]}const items=AREAS.flatMap(a=>shuffle(fallbackQuestions.filter(q=>q.area===a)).slice(0,2));diagnostic={items:shuffle(items),i:0,answers:[]};save();renderDiagnostic()}
function renderDiagnostic(){const q=diagnostic.items[diagnostic.i];app.innerHTML=`<div class="diagnostic"><div class="diag-top"><img src="${mascotUrl}"><div><b>Diagnóstico EstudAI</b><span>${diagnostic.i+1}/${diagnostic.items.length}</span></div></div><div class="diag-card"><span class="eyebrow">${q.area}</span><h2>${questionText(q.q)}</h2><div class="answers">${q.a.map((a,i)=>`<button data-diag-answer="${i}"><b>${String.fromCharCode(65+i)}</b><span>${questionText(a)}</span></button>`).join('')}</div></div></div>`;document.querySelectorAll('[data-diag-answer]').forEach(b=>b.onclick=()=>{diagnostic.answers.push(Number(b.dataset.diagAnswer));if(diagnostic.i<diagnostic.items.length-1){diagnostic.i++;renderDiagnostic()}else finishDiagnostic()})}
function finishDiagnostic(){const by={};AREAS.forEach(a=>by[a]=[0,0]);diagnostic.items.forEach((q,i)=>{by[q.area][1]++;if(diagnostic.answers[i]===q.c)by[q.area][0]++});AREAS.forEach(a=>{if(by[a][1])state.difficultyScores[a]=pct(by[a][0],by[a][1])});state.diagnosticDone=true;save();const weak=state.selfReportedWeak||AREAS[0];app.innerHTML=`<div class="plan-loading"><img src="${mascotUrl}"><div class="spinner"></div><h2>Montando seu plano personalizado… 🐶✨</h2><p>Seu foco principal será ${weak}, sem abandonar as outras áreas.</p></div>`;setTimeout(()=>{app.innerHTML=shell(`<div class="diag-done"><img src="${mascotUrl}"><h1>Plano personalizado pronto! 🎉</h1><p>Você escolheu <b>${weak}</b> como foco principal. Seus resultados vão ajustar o reforço das outras matérias, sem trocar sua prioridade.</p><button class="primary" data-action="finish-onboarding">Começar a estudar ✨</button></div>`);bind()},900)}'''
s,n=re.subn(r'function diagnosticOverlay\(\)\{.*?\}\nfunction startDiagnostic\(\)\{.*?\}\nfunction renderDiagnostic\(\)\{.*?\}\nfunction finishDiagnostic\(\)\{.*?\}\n\nfunction profPanel',wizard+'\n\nfunction profPanel',s,count=1,flags=re.S)
if n!=1: raise SystemExit('wizard patch failed')

send = r'''async function sendProf(){const input=document.querySelector('#profInput'),text=input?.value.trim();if(!text)return;state.chat.push({role:'user',text});save();renderProfPanel();const typing=document.querySelector('#profTyping');if(typing)typing.innerHTML='<div class="msg assistant typing">Pensando na melhor forma de te explicar… 🐶💭✨</div>';setTimeout(()=>{state.chat.push({role:'assistant',text:friendlyAnswer(localProfAnswer(text))});save();renderProfPanel()},450)}
function renderProfPanel'''
s,n=re.subn(r'async function sendProf\(\)\{.*?\}\nfunction renderProfPanel',send,s,count=1,flags=re.S)
if n!=1: raise SystemExit('prof patch failed')

s=s.replace("function bind(){",'''function bind(){document.querySelectorAll('[data-survey-answer]').forEach(b=>b.onclick=()=>{onboardingAnswers[onboardingStep]=Number(b.dataset.surveyAnswer);render()});''',1)
s=s.replace("async function action(a,b){if(a==='open-prof')", "async function action(a,b){if(a==='next-survey'){onboardingStep=Math.min(3,onboardingStep+1);render()}else if(a==='open-prof')",1)

render = r'''function render(){document.body.classList.toggle('quiz-active',!!(quiz&&!quiz.saved));let content=quiz?(quiz.saved?finishQuiz():quizView()):({home,desempenho,simulados,redacao,perfil}[state.tab]||home)();app.innerHTML=shell(content);bind();if(!state.diagnosticDone&&!quiz){app.insertAdjacentHTML('beforeend',diagnosticOverlay());bind()}}
async function initStatusBar(){try{await StatusBar.setOverlaysWebView({overlay:false});await StatusBar.setBackgroundColor({color:'#0B67B2'});await StatusBar.setStyle({style:Style.Light})}catch{document.documentElement.classList.add('status-fallback')}}'''
s,n=re.subn(r'function render\(\)\{.*?\}\n\nasync function initStatusBar\(\)\{.*?\}',render,s,count=1,flags=re.S)
if n!=1: raise SystemExit('render/status patch failed')

p.write_text(s,encoding='utf-8')

css=pathlib.Path('styles.css')
c=css.read_text(encoding='utf-8')
c += r'''
.topbar{padding-top:calc(14px + max(env(safe-area-inset-top),24px));min-height:92px}
.diagnostic,.plan-loading,.splash{padding-top:max(env(safe-area-inset-top),24px)}
main{padding-bottom:120px}.quiz-shell{padding-bottom:22px}.quiz-shell main{padding-bottom:120px}
.quiz-active .bottomnav,.quiz-active .prof-fab{display:none!important}
.quiz-bar{bottom:0;z-index:25;padding:16px 0 22px;background:linear-gradient(180deg,rgba(246,249,251,0),#f6f9fb 26%)}
.question-card{padding-bottom:28px}.question-card .qtext{font-size:17px!important;font-weight:400!important;line-height:1.65!important;color:#26374d!important;white-space:pre-line}.question-command{font-weight:750!important;color:#132238!important;margin-top:20px}.question-card strong{font-weight:800}.question-card em{font-style:italic}.answers button span{font-size:16px;line-height:1.45;font-weight:500}
.question-media{margin:18px 0}.question-media img{display:block;max-width:100%;max-height:360px;object-fit:contain;border-radius:18px;margin:auto}.question-media figcaption{text-align:right;font-size:10px;margin-top:5px}.question-media a{color:#8290a0;text-decoration:none}
.prof-fab{width:58px;height:58px;padding:6px;right:14px;bottom:94px}.prof-fab span{display:none}.prof-fab img{width:46px!important;height:46px!important}
.metrics-hero{background:linear-gradient(135deg,#0b67b2 0%,#0b99b7 34%,#07854a 70%,#d8b928 120%)}.metrics-hero .eyebrow{background:rgba(255,255,255,.16)}.streak-banner{background:rgba(255,255,255,.88);color:#16535f}.focus-summary{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}.focus-summary>div{background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.25);padding:12px;border-radius:16px}.focus-summary small,.focus-summary b{display:block}.focus-summary b{font-size:18px;margin-top:4px}.green-card{background:#e6f7ed;color:#087a48}.aqua-card{background:#e4f5f8;color:#087387}.purple-card{background:#eaf5ff;color:#0b67b2}.evo-col i{background:linear-gradient(180deg,#0b67b2,#07854a,#ffd132)}
.result-recommendation{margin:16px auto;max-width:540px;text-align:left;padding:16px 18px;border:1px solid #d9e5e9;border-radius:18px;background:linear-gradient(135deg,#eaf5ff,#fff8d6,#edf8f1)}.result-recommendation p{margin:7px 0 0}
.review-tags{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.review-tags span{font-size:12px;background:#eef6fa;color:#23506d;border-radius:999px;padding:6px 9px}.review-explain{margin-top:12px;background:#f7fafb;border-radius:14px;padding:12px}.review-explain p{margin:5px 0;line-height:1.5}
.onboard-card.compact{max-width:560px}.wizard-progress{height:7px;background:#e9eef1;border-radius:999px;overflow:hidden;margin:12px 0 4px}.wizard-progress i{display:block;height:100%;background:linear-gradient(90deg,#0b67b2,#07854a,#ffd132)}.survey-q.single{display:grid;gap:9px;margin:18px 0}.survey-choice{border:1.5px solid #dce5ea;background:#fff;border-radius:16px;padding:13px;text-align:left;font-weight:750}.survey-choice.selected{border-color:#0b67b2;background:linear-gradient(135deg,#eaf5ff,#eef9f2);color:#075d98}.plan-loading{text-align:center;padding:100px 24px}.plan-loading img{width:110px;height:110px;object-fit:cover;border-radius:30px;margin-bottom:18px}
@media(max-width:650px){.topbar{padding:calc(10px + max(env(safe-area-inset-top),24px)) 14px 10px}.brand img{width:40px;height:40px}.topstats span{font-size:10px;padding:7px 8px}.focus-summary{grid-template-columns:1fr}.question-card{padding:16px}.question-card .qtext{font-size:16px!important}.prof-fab{bottom:88px}}
'''
css.write_text(c,encoding='utf-8')
print('video QA fixes applied')
